DROP TABLE IF EXISTS `user_events`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `user_events` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `client_id` bigint(20) unsigned DEFAULT NULL,
  `behavioral_profile_id` bigint(20) unsigned DEFAULT NULL,
  `email` varchar(255) NOT NULL,
  `event_type` varchar(255) NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `user_events_email_event_type_index` (`email`,`event_type`),
  KEY `user_events_created_at_index` (`created_at`),
  KEY `user_events_email_index` (`email`),
  KEY `user_events_client_id_index` (`client_id`),
  KEY `user_events_behavioral_profile_id_index` (`behavioral_profile_id`),
  CONSTRAINT `user_events_behavioral_profile_id_foreign` FOREIGN KEY (`behavioral_profile_id`) REFERENCES `behavioral_profiles` (`id`) ON DELETE SET NULL,
  CONSTRAINT `user_events_client_id_foreign` FOREIGN KEY (`client_id`) REFERENCES `clients` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=2037 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
